+    public void testCalculateMAD() {
+        assertThat(DataTiersUsageTransportAction.computeMedianAbsoluteDeviation(new TDigestState(10)), equalTo(0L));
+
+        TDigestState sketch = new TDigestState(randomDoubleBetween(0, 1000, false));
+        sketch.add(1);
+        sketch.add(1);
+        sketch.add(2);
+        sketch.add(2);
+        sketch.add(4);
+        sketch.add(6);
+        sketch.add(9);
